using System;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

namespace PriceHawk
{
    public class PriceHawkApp : MonoBehaviour
    {
        [Serializable] public class Product { public string id, name; public int original, price; public Product(string i,string n,int o,int p){id=i;name=n;original=o;price=p;} }
        [Serializable] public class PriceAlert { public string id, productId; public int target; public bool triggered; }
        [Serializable] private class SaveData { public List<Product> products = new List<Product>(); public List<PriceAlert> alerts = new List<PriceAlert>(); }

        static readonly Color Bg = Hex("0D0F14"), Surface = Hex("161B24"), Surface2 = Hex("1E2535"), Border = Hex("2A3347"), Green = Hex("00E5A0"), Blue = Hex("0099FF"), Warn = Hex("FF6B35"), Orange = Hex("FF9900"), White = Hex("E8EDF5"), Muted = Hex("7A8BA8");
        readonly List<Product> products = new List<Product>{new Product("15pm","iPhone 15 Pro Max",159900,134900),new Product("15p","iPhone 15 Pro",134900,119900),new Product("15pl","iPhone 15 Plus",89900,79900),new Product("15","iPhone 15",79900,69900),new Product("14","iPhone 14",69900,59900),new Product("13","iPhone 13",59900,49900)};
        readonly List<PriceAlert> alerts = new List<PriceAlert>();
        Canvas canvas; RectTransform body; string tab="Home", selectedId="15pm"; int range=1; InputField targetInput;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)] static void Boot(){ if(FindObjectOfType<PriceHawkApp>()==null) new GameObject("PriceHawkApp").AddComponent<PriceHawkApp>(); }
        void Awake(){ Load(); Build(); }
        Product Selected { get { return products.Find(p=>p.id==selectedId) ?? products[0]; } }
        void Load(){try{var json=PlayerPrefs.GetString("pricehawk-v1","");if(json.Length==0)return;var saved=JsonUtility.FromJson<SaveData>(json);if(saved==null)return;foreach(var p in saved.products){var current=products.Find(x=>x.id==p.id);if(current!=null)current.price=p.price;}if(saved.alerts!=null)alerts.AddRange(saved.alerts);}catch(Exception e){Debug.LogWarning("PriceHawk save could not be loaded: "+e.Message);}}
        void Save(){var s=new SaveData{products=products,alerts=alerts};PlayerPrefs.SetString("pricehawk-v1",JsonUtility.ToJson(s));PlayerPrefs.Save();}

        void Build(){
            var root=new GameObject("PriceHawk Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=root.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;
            var scaler=root.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(900,1600);scaler.matchWidthOrHeight=.5f;
            if(FindObjectOfType<EventSystem>()==null)new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));
            var background=Panel(root.transform,"Background",Bg);Stretch(background,0,0,0,0);
            var header=Panel(background,"Header",Surface);Anchor(header,0,1,1,1);header.sizeDelta=new Vector2(0,105);header.anchoredPosition=new Vector2(0,-52);
            Label(header,"PRICEHAWK",24,Green,TextAnchor.MiddleLeft,new Vector2(30,0),new Vector2(400,90));
            var scrollObj=new GameObject("Content Scroll",typeof(RectTransform),typeof(ScrollRect),typeof(Image),typeof(Mask));scrollObj.transform.SetParent(background,false);var sr=scrollObj.GetComponent<ScrollRect>();sr.horizontal=false;sr.vertical=true;sr.movementType=ScrollRect.MovementType.Clamped;scrollObj.GetComponent<Image>().color=Bg;scrollObj.GetComponent<Mask>().showMaskGraphic=false;
            Anchor(scrollObj.GetComponent<RectTransform>(),0,0,1,1);scrollObj.GetComponent<RectTransform>().offsetMin=new Vector2(0,94);scrollObj.GetComponent<RectTransform>().offsetMax=new Vector2(0,-105);
            var content=CreateRect("Content",scrollObj.transform);content.anchorMin=new Vector2(0,1);content.anchorMax=new Vector2(1,1);content.pivot=new Vector2(.5f,1);content.anchoredPosition=Vector2.zero;content.sizeDelta=new Vector2(0,1800);sr.content=content;body=content;
            var nav=Panel(background,"Navigation",Surface);Anchor(nav,0,0,1,0);nav.sizeDelta=new Vector2(0,94);nav.anchoredPosition=new Vector2(0,47);
            string[] tabs={"Home","Product","Alerts","Spend"};for(int i=0;i<tabs.Length;i++){string t=tabs[i];var b=Button(nav,t,()=>Show(t),i*225,225,94);b.GetComponentInChildren<Text>().fontSize=18;}
            Render();
        }
        void Show(string t){tab=t;Render();}
        void Render(){foreach(Transform child in body)Destroy(child.gameObject);targetInput=null;switch(tab){case "Home":Dashboard();break;case "Product":ProductPage();break;case "Alerts":AlertsPage();break;default:SpendPage();break;}}
        void Dashboard(){
            int active=alerts.FindAll(a=>!a.triggered).Count, hit=alerts.Count-active;
            Card("SUMMARY",10,170);RowText("Total saved",Inr(6240)+" lifetime  ·  "+Inr(1840)+" this month",Green,30,75);RowText("Active alerts",active+" active  ·  "+hit+" targets reached",White,30,120);RowText("Phones tracked",products.Count+"  ·  all below launch price",White,470,75);RowText("Amazon spend",Inr(12000)+" this month",White,470,120);
            Label(body,"PRICE DROPS TODAY",18,White,TextAnchor.MiddleLeft,new Vector2(24,-205),new Vector2(850,45));
            int y=265;foreach(var p in products){var pp=p;var c=Card(p.name, y,120);Label(c,"Launch "+Inr(p.original),14,Muted,TextAnchor.MiddleLeft,new Vector2(20,-55),new Vector2(510,30));Label(c,Inr(p.price)+"   "+Mathf.RoundToInt((p.original-p.price)*100f/p.original)+"% off",19,Green,TextAnchor.MiddleRight,new Vector2(570,-55),new Vector2(230,30));Button(c,"View price history",()=>{selectedId=pp.id;Show("Product");},0,220,43).GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-73);y+=132;}
            body.sizeDelta=new Vector2(0,y+30);
        }
        void ProductPage(){var p=Selected;Label(body,"CHOOSE A PHONE",14,Muted,TextAnchor.MiddleLeft,new Vector2(22,-8),new Vector2(300,35));int cx=20;foreach(var item in products){var it=item;Button(body,it.name,()=>{selectedId=it.id;Render();},cx,155,40);cx+=160;}Card(p.name,62,245);Label(body,Inr(p.price)+"     "+Inr(p.original),29,Green,TextAnchor.MiddleLeft,new Vector2(40,-111),new Vector2(700,48));Label(body,Mathf.RoundToInt((p.original-p.price)*100f/p.original)+"% off  ·  Near its lowest price",15,Muted,TextAnchor.MiddleLeft,new Vector2(40,-157),new Vector2(760,35));Button(body,"Set price alert",()=>Show("Alerts"),35,360,54).GetComponent<RectTransform>().anchoredPosition=new Vector2(35,-235);Button(body,"Simulate ₹2,000 drop",()=>{Drop(p,2000);},420,420,54).GetComponent<RectTransform>().anchoredPosition=new Vector2(420,-235);
            Card("PRICE HISTORY  ·  "+new[]{"1M","3M","6M","1Y"}[range],325,270);Button(body,"1M",()=>{range=0;Render();},30,130,42).GetComponent<RectTransform>().anchoredPosition=new Vector2(30,-340);Button(body,"3M",()=>{range=1;Render();},170,130,42).GetComponent<RectTransform>().anchoredPosition=new Vector2(170,-340);Button(body,"6M",()=>{range=2;Render();},310,130,42).GetComponent<RectTransform>().anchoredPosition=new Vector2(310,-340);Button(body,"1Y",()=>{range=3;Render();},450,130,42).GetComponent<RectTransform>().anchoredPosition=new Vector2(450,-340);DrawChart(body,p,420);
            Card("COMPARE STORES",610,360);string[] stores={"Amazon","Flipkart","Reliance","Croma","Apple Store"};float[] factors={1,1.023f,1.04f,1.05f,(float)p.original/p.price};for(int i=0;i<stores.Length;i++){int price=i==4?p.original:Mathf.RoundToInt(p.price*factors[i]/100f)*100;Label(body,stores[i],14,White,TextAnchor.MiddleLeft,new Vector2(35,-680-i*52),new Vector2(180,35));Bar(body,220,-680-i*52,Mathf.Min(1,price/(float)p.original),i==0?Green:Blue);Label(body,Inr(price),14,White,TextAnchor.MiddleRight,new Vector2(700,-680-i*52),new Vector2(160,35));}body.sizeDelta=new Vector2(0,1030);
        }
        void AlertsPage(){Label(body,"CHOOSE AN IPHONE",14,Muted,TextAnchor.MiddleLeft,new Vector2(22,-8),new Vector2(300,35));int cx=20;foreach(var item in products){var it=item;Button(body,it.name,()=>{selectedId=it.id;Render();},cx,155,40);cx+=160;}var p=Selected;Card(p.name+"  ·  Current "+Inr(p.price),62,210);Label(body,"ALERT ME WHEN PRICE DROPS TO",14,Muted,TextAnchor.MiddleLeft,new Vector2(40,-118),new Vector2(600,35));targetInput=Input(body,"e.g. 120000",new Vector2(40,-164),new Vector2(750,55));Button(body,"Set price alert",AddAlert,40,750,52).GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-232);
            Card("YOUR ALERTS",285,Mathf.Max(150,alerts.Count*100+80));int y=340;if(alerts.Count==0)Label(body,"No alerts yet. Set one above.",15,Muted,TextAnchor.MiddleLeft,new Vector2(35,-y),new Vector2(700,40));foreach(var a in alerts.ToArray()){var alert=a;var product=products.Find(x=>x.id==a.productId);if(product==null)continue;Label(body,product.name+"  ·  target "+Inr(a.target)+"  ·  now "+Inr(product.price)+(a.triggered?"  ·  REACHED":"  ·  watching"),15,a.triggered?Green:White,TextAnchor.MiddleLeft,new Vector2(35,-y),new Vector2(660,45));Button(body,"Delete",()=>{alerts.Remove(alert);Save();Render();},700,130,40).GetComponent<RectTransform>().anchoredPosition=new Vector2(-20,-y);y+=92;}
            Card("TEST YOUR ALERT",400+alerts.Count*100,155);Button(body,"Drop ₹5,000",()=>Drop(p,5000),40,360,50).GetComponent<RectTransform>().anchoredPosition=new Vector2(40,-440-alerts.Count*100);Button(body,"Reset prices",Reset,420,360,50).GetComponent<RectTransform>().anchoredPosition=new Vector2(420,-440-alerts.Count*100);body.sizeDelta=new Vector2(0,650+alerts.Count*100);
        }
        void SpendPage(){Card("SPENT IN JULY",10,135);Label(body,Inr(12000)+"  ·  "+Inr(2400)+" more than June",23,White,TextAnchor.MiddleLeft,new Vector2(35,-70),new Vector2(800,40));Card("AMAZON ORDERS",160,135);Label(body,"6 orders  ·  "+Inr(2000)+" per order",22,White,TextAnchor.MiddleLeft,new Vector2(35,-220),new Vector2(800,40));Card("STUDENT BUDGET",310,190);Label(body,"Used "+Inr(12000)+" of "+Inr(15000)+"  ·  "+Inr(3000)+" left",17,White,TextAnchor.MiddleLeft,new Vector2(35,-365),new Vector2(800,35));Bar(body,35,-420,.8f,Orange);Label(body,"80% used, 12 days left in the month",14,Muted,TextAnchor.MiddleLeft,new Vector2(35,-450),new Vector2(800,30));Card("WHERE IT WENT",520,300);string[] cats={"Electronics","Books","Clothing","Stationery"};int[] vals={8400,1800,1200,600};for(int i=0;i<4;i++){Label(body,cats[i]+"  "+Inr(vals[i]),15,White,TextAnchor.MiddleLeft,new Vector2(35,-575-i*55),new Vector2(800,34));Bar(body,350,-575-i*55,vals[i]/12000f,new[]{Orange,Blue,Green,Muted}[i]);}Card("LAST SIX MONTHS",840,260);int[] months={7200,9400,6800,11200,9600,12000};string[] names={"Feb","Mar","Apr","May","Jun","Jul"};for(int i=0;i<6;i++){float h=months[i]/12000f*130;var bar=Panel(body,"Month",i==5?Orange:Surface2);bar.sizeDelta=new Vector2(70,h);bar.anchoredPosition=new Vector2(55+i*135,-1040);Label(body,names[i],13,Muted,TextAnchor.MiddleCenter,new Vector2(40+i*135,-1055),new Vector2(100,25));}Card("RECENT AMAZON ORDERS",1130,340);string[] recent={"NCERT Physics Class 12  ·  ₹280","boAt Bassheads 100 Wired  ·  ₹349","Syska 9W LED Bulb (6-pack)  ·  ₹399","Classmate Notebook (10-pack)  ·  ₹420","Phone Case, Redmi Note 12  ·  ₹199","Logitech K380 Keyboard  ·  ₹2,499"};for(int i=0;i<recent.Length;i++)Label(body,recent[i],15,White,TextAnchor.MiddleLeft,new Vector2(35,-1190-i*43),new Vector2(800,35));body.sizeDelta=new Vector2(0,1510);}
        void DrawChart(RectTransform parent,Product p,int top){var values=History(p);int n=values.Length;for(int i=0;i<n;i++){float x=50+i*780f/(n-1);float norm=(values[i]-Min(values))/(float)Mathf.Max(1,Max(values)-Min(values));var dot=Panel(parent,"Price point",i==n-1?Green:Blue);dot.sizeDelta=new Vector2(9,9);dot.anchoredPosition=new Vector2(x,-top-185+norm*135);if(i>0){var prev=values[i-1];float py=(prev-Min(values))/(float)Mathf.Max(1,Max(values)-Min(values));var line=Panel(parent,"Line",new Color(Green.r,Green.g,Green.b,.7f));float dx=780f/(n-1),dy=(norm-py)*135;line.sizeDelta=new Vector2(Mathf.Sqrt(dx*dx+dy*dy),3);line.anchoredPosition=new Vector2(x-dx/2,-top-185+norm*135-dy/2);line.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(dy,dx)*Mathf.Rad2Deg);}}Label(parent,"Price over selected period  ·  latest "+Inr(p.price),13,Muted,TextAnchor.MiddleLeft,new Vector2(30,-top-235),new Vector2(800,30));}
        int[] History(Product p){int count=new[]{15,24,30,40}[range];float start=range==0?1.03f:range==1?1.08f:range==2?1.14f:(float)p.original/p.price;var a=new int[count];for(int i=0;i<count;i++){float t=i/(float)(count-1);a[i]=Mathf.RoundToInt((p.price*(start+(1-start)*Mathf.Pow(1-t,.7f)))/100)*100;}a[count-1]=p.price;return a;}
        void AddAlert(){int t;var p=Selected;if(targetInput==null||!int.TryParse(targetInput.text,out t)||t<=0){Message("Enter a target price");return;}if(t>=p.price){Message("Pick a target below the current price of "+Inr(p.price));return;}alerts.Insert(0,new PriceAlert{id=Guid.NewGuid().ToString(),productId=p.id,target=t});Save();Render();Message("Price alert set for "+Inr(t));}
        void Drop(Product p,int amount){p.price=Mathf.Max(1000,p.price-amount);foreach(var a in alerts)if(!a.triggered&&a.productId==p.id&&p.price<=a.target){a.triggered=true;Message("Price alert: "+p.name+" is now "+Inr(p.price));}Save();Render();}
        void Reset(){foreach(var p in products){var basePrice=new[]{134900,119900,79900,69900,59900,49900};p.price=basePrice[products.IndexOf(p)];}foreach(var a in alerts)a.triggered=false;Save();Render();}
        void Message(string s){Debug.Log(s);}
        void RowText(string title,string value,Color valueColor,int x,int y){Label(body,title,13,Muted,TextAnchor.MiddleLeft,new Vector2(x,-y),new Vector2(190,26));Label(body,value,17,valueColor,TextAnchor.MiddleLeft,new Vector2(x,-y-27),new Vector2(380,30));}
        static int Min(int[] a){int v=int.MaxValue;foreach(int x in a)v=Mathf.Min(v,x);return v;}static int Max(int[] a){int v=int.MinValue;foreach(int x in a)v=Mathf.Max(v,x);return v;}
        static string Inr(int n){string s=Mathf.RoundToInt(n).ToString(CultureInfo.InvariantCulture);if(s.Length<=3)return "₹"+s;string last=s.Substring(s.Length-3),rest=s.Substring(0,s.Length-3);for(int i=rest.Length-2;i>0;i-=2)rest=rest.Insert(i,",");return "₹"+rest+","+last;}
        static Color Hex(string h){Color c;ColorUtility.TryParseHtmlString("#"+h,out c);return c;}
        RectTransform Card(string title,int top,int height){var r=Panel(body,title,Surface);Anchor(r,0,1,1,1);r.sizeDelta=new Vector2(-36,height);r.anchoredPosition=new Vector2(0,-top-height/2f);Label(r,title,18,White,TextAnchor.MiddleLeft,new Vector2(20,-22),new Vector2(780,35));return r;}
        RectTransform Panel(Transform parent,string name,Color color){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);g.GetComponent<Image>().color=color;return g.GetComponent<RectTransform>();}
        Text Label(Transform parent,string value,int size,Color color,TextAnchor align,Vector2 pos,Vector2 dims){var g=new GameObject("Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);var t=g.GetComponent<Text>();t.text=value;t.font=Resources.GetBuiltinResource<Font>("Arial.ttf");t.fontSize=size;t.color=color;t.alignment=align;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Truncate;t.supportRichText=false;var r=t.rectTransform;r.anchorMin=new Vector2(0,1);r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=dims;return t;}
        Button Button(Transform parent,string title,Action action,int left,int width,int height){var r=Panel(parent,"Button · "+title,Surface2);r.sizeDelta=new Vector2(width,height);r.anchorMin=new Vector2(0,1);r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(left,-10);var b=r.gameObject.AddComponent<Button>();b.targetGraphic=r.GetComponent<Image>();b.onClick.AddListener(()=>action());var t=Label(r,title,14,White,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(width-8,height-4));t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=Vector2.zero;t.rectTransform.offsetMax=Vector2.zero;return b;}
        InputField Input(Transform parent,string placeholder,Vector2 pos,Vector2 size){var r=Panel(parent,"Target price input",Surface2);r.anchorMin=new Vector2(0,1);r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=size;var t=Label(r,"",20,White,TextAnchor.MiddleLeft,new Vector2(12,-size.y/2),new Vector2(size.x-24,size.y-8));t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=new Vector2(12,4);t.rectTransform.offsetMax=new Vector2(-12,-4);var field=r.gameObject.AddComponent<InputField>();field.textComponent=t;field.contentType=InputField.ContentType.IntegerNumber;var ph=Label(r,placeholder,17,Muted,TextAnchor.MiddleLeft,Vector2.zero,new Vector2(size.x-24,size.y-8));ph.rectTransform.anchorMin=Vector2.zero;ph.rectTransform.anchorMax=Vector2.one;ph.rectTransform.offsetMin=new Vector2(12,4);ph.rectTransform.offsetMax=new Vector2(-12,-4);field.placeholder=ph;return field;}
        void Bar(Transform parent,int x,int y,float amount,Color color){var track=Panel(parent,"Bar track",Border);track.anchorMin=new Vector2(0,1);track.anchorMax=new Vector2(0,1);track.pivot=new Vector2(0,1);track.anchoredPosition=new Vector2(x,y+8);track.sizeDelta=new Vector2(360,12);var fill=Panel(track,"Bar",color);fill.anchorMin=new Vector2(0,0);fill.anchorMax=new Vector2(0,1);fill.pivot=new Vector2(0,0.5f);fill.anchoredPosition=Vector2.zero;fill.sizeDelta=new Vector2(360*Mathf.Clamp01(amount),0);}
        static RectTransform CreateRect(string name,Transform p){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(p,false);return g.GetComponent<RectTransform>();}
        static void Stretch(RectTransform r,int l,int b,int rr,int t){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(l,b);r.offsetMax=new Vector2(-rr,-t);}
        static void Anchor(RectTransform r,float x0,float y0,float x1,float y1){r.anchorMin=new Vector2(x0,y0);r.anchorMax=new Vector2(x1,y1);r.pivot=new Vector2(.5f,.5f);}
    }
}
